"""Explicit preview and reversible selection of a synthetic commercial catalogue."""
HTML='''<section class="card files-section" id="commercial-catalogue-panel"><div class="files-section-title"><span class="files-number">C</span><h2>CATÁLOGO COMERCIAL · EMPRESA ACTIVA</h2></div><p id="catalogue-active-company"></p><p>Incorpora SKU, descripción, proveedor, coste y PVP para preparar propuestas. No añade compras, ventas ni existencias. Los datos financieros y el inventario anteriores se conservan.</p><p>Esta ruta admite catálogos ficticios XLSX/CSV de hasta 20.000 filas y 10 MiB. Cabeceras: <strong>sku, descripcion, proveedor, coste, precio_pvp_recomendado, estado_baja, subfama</strong>. Las columnas adicionales se conservan en el original y no se incorporan.</p><div class="files-step"><label>Archivo de catálogo<input id="catalogue-file" type="file" accept=".xlsx,.csv"></label><div class="fields"><label>Hoja de Excel (vacío: primera hoja)<input id="catalogue-sheet"></label><label>Formato de números escritos como texto<select id="catalogue-numbers"><option value="ES">Español: 1.234,56</option><option value="EN">Internacional: 1,234.56</option></select></label></div><label><input id="catalogue-ack" type="checkbox" style="display:inline;width:auto"> Confirmo empresa ficticia, venta por unidades y coste/PVP por unidad en EUR sin IVA.</label><p>Las fórmulas de PVP quedan pendientes: no se ejecutan ni se toman sus resultados guardados. Los artículos de baja se excluyen de esta incorporación. No se eliminan fichas del catálogo original ni se convierten embalajes. Un proveedor nuevo recibe un código propuesto; su nombre no lo vincula automáticamente a facturas anteriores.</p><button id="catalogue-preview" type="button">Comprobar catálogo y ver cambios</button></div><div id="catalogue-review" class="files-step" hidden><h3>CAMBIOS PROPUESTOS · TODAVÍA SIN INCORPORAR</h3><p id="catalogue-preview-summary"></p><div id="catalogue-preview-rows" class="scroll"></div><p>Se mantienen las fichas originales que no aparecen en el archivo. Para SKU existentes se conserva identidad, descripción y proveedor; solo se preparan sus referencias comerciales. Los PVP fijos no tienen vigencia acreditada. Una tarifa previamente seleccionada conserva su prioridad.</p><button id="catalogue-commit" type="button" class="primary" disabled>Incorporar catálogo a las propuestas</button></div><div class="fields"><label>Responsable<input id="catalogue-actor" maxlength="500"></label><label>Motivo de incorporación o retirada<input id="catalogue-reason" maxlength="500"></label></div><p id="catalogue-current"></p><button id="catalogue-clear" type="button" disabled>Retirar el catálogo seleccionado</button><p id="catalogue-notice" class="files-notice" role="status"></p></section>'''
JS=r'''
let catalogueTicket=null,catalogueSequence=0,catalogueBusy=false;
function invalidateCommercialCatalogue(){catalogueSequence++;catalogueTicket=null;$('catalogue-review').hidden=true;$('catalogue-commit').disabled=true}
function renderCommercialCatalogue(){invalidateCommercialCatalogue();$('catalogue-active-company').textContent='Empresa activa: '+(state.info.company.legal_name||state.info.company.company_id)+' · corte documental '+stockDate(state.info.as_of_date)+'. El archivo no acredita una fecha nueva de inventario o balance.';const c=state.commercial_catalogue;$('catalogue-current').textContent=c?'Catálogo seleccionado: '+c.filename+' · revisión '+c.revision+' · '+c.article_count+' artículos del archivo. Sin existencias ni vigencia de PVP documentadas.':'Sin catálogo comercial adicional seleccionado.';$('catalogue-clear').disabled=!c;$('catalogue-preview').disabled=catalogueBusy;$('catalogue-file').value='';$('catalogue-ack').checked=false}
['catalogue-file','catalogue-sheet','catalogue-numbers','catalogue-ack'].forEach(id=>$(id).addEventListener('change',invalidateCommercialCatalogue));
$('catalogue-preview').onclick=async()=>{invalidateCommercialCatalogue();const sequence=catalogueSequence,dataset=$('dataset').value,file=$('catalogue-file').files[0];if(!file){$('catalogue-notice').textContent='Selecciona el catálogo XLSX o CSV.';return}if(!$('catalogue-ack').checked){$('catalogue-notice').textContent='Confirma naturaleza ficticia, unidades y precios netos en EUR.';return}if(file.size>10*1024*1024){$('catalogue-notice').textContent='Máximo 10 MiB por archivo.';return}catalogueBusy=true;$('catalogue-preview').disabled=true;$('catalogue-notice').textContent='Leyendo y comprobando catálogo…';try{const options={dataset_id:dataset,context_fingerprint:state.documentary_context.fingerprint,acknowledge_synthetic_units_eur_net:true,sheet:$('catalogue-sheet').value,number_format:$('catalogue-numbers').value};const r=await api('/api/catalogue/preview',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-EIOS-Token':token,'X-EIOS-Filename':encodeURIComponent(file.name),'X-EIOS-Catalogue':encodeURIComponent(JSON.stringify(options))},body:file});if(sequence!==catalogueSequence||dataset!==$('dataset').value)return;catalogueTicket=r.ticket;$('catalogue-review').hidden=false;$('catalogue-preview-summary').textContent=r.rows+' filas · '+r.new_articles+' artículos nuevos · '+r.updated_articles+' SKU existentes con referencias comerciales · '+r.inactive_excluded+' bajas excluidas · '+r.pending_prices+' PVP pendientes · '+r.error_count+' errores. Stock, caja/bancos, vencimientos e históricos: sin cambios.';receptionTable('catalogue-preview-rows',['SKU','Descripción','Coste catálogo EUR/ud.','PVP neto EUR/ud.','Fila'],r.sample.map(a=>[a.article_id,a.description,a.catalogue_unit_cost,a.recommended_sale_price,a.source_row]));$('catalogue-notice').textContent=r.errors.length?r.errors.map(e=>'Fila '+e.row+': '+e.message).join(' · '):'Revisa los cambios. Completa responsable y motivo antes de incorporar.';$('catalogue-commit').disabled=!r.ticket}catch(e){if(sequence===catalogueSequence)$('catalogue-notice').textContent=e.message}finally{catalogueBusy=false;$('catalogue-preview').disabled=false}};
async function changeCommercialCatalogue(clear){if(catalogueBusy)return;const dataset=$('dataset').value,sequence=catalogueSequence,payload={dataset_id:dataset,context_fingerprint:state.documentary_context.fingerprint,ticket:catalogueTicket,actor:$('catalogue-actor').value,reason:$('catalogue-reason').value};if(!clear&&!catalogueTicket)return;catalogueBusy=true;$('catalogue-commit').disabled=true;$('catalogue-clear').disabled=true;try{const r=await api(clear?'/api/catalogue/clear':'/api/catalogue/commit',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify(payload)});if(dataset!==$('dataset').value||sequence!==catalogueSequence)return;await refresh();$('catalogue-notice').textContent=clear?'Catálogo retirado. Se recuperan las fichas y referencias anteriores. Las propuestas guardadas conservan su contenido.':r.status==='UNCHANGED'?'Ese catálogo ya estaba seleccionado. No se ha duplicado.':'Catálogo incorporado. Ya puedes seleccionar sus artículos en Propuestas y Propuestas de venta. No se han creado existencias, facturas ni movimientos de caja.'}catch(e){if(dataset===$('dataset').value)$('catalogue-notice').textContent=e.message}finally{catalogueBusy=false;$('catalogue-preview').disabled=false;$('catalogue-commit').disabled=!catalogueTicket;$('catalogue-clear').disabled=!state.commercial_catalogue}}
$('catalogue-commit').onclick=()=>changeCommercialCatalogue(false);$('catalogue-clear').onclick=()=>changeCommercialCatalogue(true);
'''
